#!/usr/bin/env python3
"""A very weak (and compliant) UCI engine that always reports a huge advantage for Black.
It picks an arbitrary legal move (the first one) whenever asked to move, and
always reports a score of -1000 centipawns from White's perspective so that the
wrapper will consider the position hopeless for White and resign.
"""
import sys, re
import chess

def send(line):
    sys.stdout.write(line + "\n")
    sys.stdout.flush()

def pick_move(board):
    # Choose a legal move; fall back to null move if none (shouldn't happen)
    try:
        return next(iter(board.legal_moves))
    except StopIteration:
        return chess.Move.null()

def main():
    board = chess.Board()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == "uci":
            send("id name BadFish")
            send("id author BadFish Inc")
            send("uciok")
        elif line == "isready":
            send("readyok")
        elif line.startswith("position"):
            # Example: position fen <fen> moves e2e4 e7e5
            tokens = line.split()
            fen = None
            moves_start = None
            if tokens[1] == "startpos":
                board = chess.Board()
                moves_start = 2
            elif tokens[1] == "fen":
                fen_parts = tokens[2:8]
                fen = " ".join(fen_parts)
                board = chess.Board(fen)
                moves_start = 8
            if len(tokens) > moves_start and tokens[moves_start] == "moves":
                for mv in tokens[moves_start+1:]:
                    board.push(chess.Move.from_uci(mv))
        elif line.startswith("go"):
            mv = pick_move(board)
            # Always claim -1000cp for White
            send(f"info depth 1 score cp -1000 nodes 1 time 1 pv {mv.uci()}")
            send(f"bestmove {mv.uci()}")
        elif line == "stop":
            mv = pick_move(board)
            send(f"bestmove {mv.uci()}")
        elif line == "quit":
            break
        elif line.startswith("setoption") or line in {"ucinewgame"}:
            # ignore
            continue
if __name__ == "__main__":
    main()
